INSERT INTO `blog_posts` (`id`, `title`, `slug`, `excerpt`, `content`, `cover_image`, `author_id`, `is_published`, `published_at`, `created_at`, `updated_at`) VALUES ('2', 'Panduan Aturan Pakai Antibiotik yang Benar dan Bahaya Resistensi', 'panduan-aturan-pakai-antibiotik-dan-resistensi', 'Mengapa obat antibiotik harus dihabiskan walau gejala sudah hilang? Simak penjelasan resmi apoteker.', 'Antibiotik adalah obat pembunuh bakteri, bukan untuk flu biasa yang disebabkan virus. Menghentikan obat antibiotik secara sepihak sebelum dosis yang disarankan habis dapat menyebabkan bakteri kebal (resistensi antibiotik).', NULL, '2', '1', '2026-09-15 03:37:08', '2026-09-22 03:37:08', '2026-09-22 03:37:08');
