INSERT INTO `faqs` (`id`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES ('1', 'Bagaimana cara memesan obat yang memerlukan resep dokter?', 'Saat proses Checkout, Anda akan diminta mengunggah foto/file resep dokter yang jelas. Tim apoteker kami akan melakukan verifikasi sebelum pesanan diproses.', '1', '1', '2026-09-22 03:37:08', '2026-09-22 03:37:08');
INSERT INTO `faqs` (`id`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES ('2', 'Berapa lama proses pengiriman obat?', 'Untuk area Bandung dan sekitarnya menggunakan Kurir Instant Apotek, pesanan dikirim dalam 1-3 jam setelah pembayaran terkonfirmasi. Untuk luar kota menggunakan JNE (1-3 hari kerja).', '2', '1', '2026-09-22 03:37:08', '2026-09-22 03:37:08');
INSERT INTO `faqs` (`id`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES ('3', 'Apakah pembayaran COD (Bayar di Tempat) tersedia?', 'Ya, metode COD tersedia untuk pilihan Kurir Instant Apotek dan metode Ambil di Toko.', '3', '1', '2026-09-22 03:37:08', '2026-09-22 03:37:08');
INSERT INTO `faqs` (`id`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES ('4', 'Apakah obat-obatan di Apotek Sehat Sentosa terjamin keasliannya?', '100% Terjamin Asli. Seluruh obat dan alat kesehatan dibeli langsung dari Distributor Resmi (PBF) terdaftar BPOM dan Kementerian Kesehatan RI.', '4', '1', '2026-09-22 03:37:08', '2026-09-22 03:37:08');
INSERT INTO `faqs` (`id`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES ('5', 'Bagaimana jika pesanan obat saya kedaluwarsa atau rusak saat diterima?', 'Kami menggaransi penggantian 100% atau refund jika obat yang diterima dalam keadaan rusak/mendekati expiry date. Anda dapat mengajukan retur melalui menu Riwayat Pesanan di Akun Anda.', '5', '1', '2026-09-22 03:37:08', '2026-09-22 03:37:08');
