INSERT INTO `settings` (`id`, `key`, `value`, `group`, `created_at`, `updated_at`) VALUES ('10', 'about', 'Apotek Sehat Sentosa berdiri sejak tahun 2020. Kami berdedikasi melayani kebutuhan kesehatan masyarakat dengan menyediakan obat-obatan asli, vitamin, suplemen, dan alat kesehatan berkualitas tinggi.', 'general', '2026-09-22 03:37:07', '2026-09-22 03:37:07');
INSERT INTO `settings` (`id`, `key`, `value`, `group`, `created_at`, `updated_at`) VALUES ('11', 'terms', 'Pembelian obat keras memerlukan resep dokter sah. Apotek berhak menolak transaksi yang tidak memenuhi ketentuan medis.', 'general', '2026-09-22 03:37:07', '2026-09-22 03:37:07');
